/** Resolves with the arguments of the next `ev` event. (With connection-state recovery on, reliable
 *  events carry one extra trailing offset argument; tests index [0]/[1] and ignore it.) */
function next<Ev extends keyof ServerToClientEvents>(s: C, ev: Ev): Promise<Parameters<ServerToClientEvents[Ev]>> {
  return new Promise((resolve) => {
    const listener = (event: string, ...args: unknown[]): void => {
      if (event !== ev) return;
      s.offAny(listener);
      resolve(args as Parameters<ServerToClientEvents[Ev]>);
    };
    s.onAny(listener);
  });
}

